// The sand quad's visuals (public/models/quadbike.glb, generated by tools/blender/quadbike.py): the vehicle by the
// crashed pods (shared/gear.ts GEAR.quad). Physics is the bike's (shared/sim.ts stepBike); this only draws it, as
// src/bike.ts draws the bike where a quad moves the same (pitched along the sand, up on its back wheels while Space is
// held, the wheels spinning with the ground speed, the bars turned with the steering, a headlight from the bikes' pool
// after dark, tracks and dust behind) and unlike it where a quad doesn't: it never leans into a turn but rolls a little
// out of it on its springs, and the front wheels steer on their own kingpins (the inside one further). So the rider does
// the leaning: hips slid to the inside, the upper body thrown over it.
//
// Every body sits on the same long flat seat and holds the same wide bars: a short rider (a dwarf, a gnome) slides
// forward until its belly is against the tank and leans over the bars until it reaches them (src/models/scavenger.ts
// ride()); its feet, too short for the footboards, go up the toe ramp at the boards' front until they find it.
//
// Behind the rider sits a passenger (shared/sim.ts PlayerState.pillion; passenger()): on the back of the seat, the
// jerry can at its back, a hand on each grab handle beside the seat, feet on the back of the footboards (short legs up
// the heel guards), sitting up straight and leaning into the turns a little after the rider.
import * as THREE from 'three/webgpu';
import { GLTFLoader, type GLTF } from 'three/addons/loaders/GLTFLoader.js';
import { biome } from '../shared/biomes.ts';
import { HITCH_BACK, HITCH_Y } from '../shared/cart.ts';
import { heightAt } from '../shared/terrain.ts';
import type { RidePose } from './players.ts';
import { addHeadlights, AIM, claimHeadlight, HEADLIGHT, releaseHeadlight, type BikePose, type Headlight } from './bike.ts';
import { bikeLandSound } from './bikeLandSound.ts';
import { TyreTrack } from './footprints.ts';
import { tyreDust } from './tyreDust.ts';
import { nightLevel } from './world/env.ts';
import { applyTier } from './tierLook.ts';

// From tools/blender/quadbike.py (its build prints them), in the quad's frame: origin on the ground between the axles,
// forward is -z. Hips over the seat's middle (top 0.82); ankles at the foot of the toe ramp (heel on the board, sole up
// the ramp), climbing up it (35°) when the legs are short; the toes along it.
const SEAT = new THREE.Vector3(0, 0.93, 0.2);
const PEG = new THREE.Vector3(0.28, 0.354, 0.072);
const CLIMB = new THREE.Vector3(0, 0.574, -0.819);
/** The seat is flat back from the tank; only the tank's nose rises a little under a rider sat right up against it. */
const PERCH = 0.1;
/** The passenger: hips on the back of the seat, the right hand round its grab handle (beside the seat, a little ahead
 *  of the hips), ankles on the back of the footboards, outboard of the rider's, climbing the heel guard when short. */
const PILLION_SEAT = new THREE.Vector3(0, 0.94, 0.63);
const PILLION_GRIP = new THREE.Vector3(0.24, 0.84, 0.47);
const PILLION_PEG = new THREE.Vector3(0.34, 0.37, 0.27);
const PILLION_CLIMB = new THREE.Vector3(0, 0.97, 0.25).normalize();
const PILLION_TOE = new THREE.Vector3(0, -0.35, -1);
/** The right grip's middle, in the Handlebar node's frame (its origin is the top of the steering column). */
const GRIP = new THREE.Vector3(0.392, 0.12, 0.135);
const BARS_PIVOT = new THREE.Vector3(0, 0.92, -0.36);
/** The column is raked 20°: the bars turn about this axis. */
const STEER_AXIS = new THREE.Vector3(0, 0.94, 0.342);
/** The headlight lens in the Handlebar node's frame (the pod in front of the bar clamp). */
const LAMP = new THREE.Vector3(0, 0.064, -0.174);
const FRONT_R = 0.3;
const REAR_R = 0.32;
const WHEELBASE = 1.22;
const TRACK = 0.88; // the rear wheels' centres apart: two tyre tracks
const KINGPINS = 0.66; // apart
const MAX_STEER = 0.55;
/** Body roll out of a turn on the springs (rad at a full corner), and how hard a corner is: sideways acceleration (m/s²)
 *  that makes a full one. */
const MAX_ROLL = 0.07;
const FULL_CORNER = 9;
const WHEELIE = 0.35; // rad the nose comes up, about the rear axle
const WHEELIE_TOW = 0.15;
const BIG_AIR = 0.6;
/** The tow ball (shared/cart.ts HITCH_BACK, HITCH_Y) in the quad's frame: on a tongue off the frame under the rack. */
const HITCH = new THREE.Vector3(0, HITCH_Y, HITCH_BACK);

let gltf: Promise<GLTF> | undefined;
/** The quad model (shared by every clone: don't change its materials), also drawn parked (src/world/vehicles.ts). */
export const loadQuadModel = () => (gltf ??= new GLTFLoader().loadAsync('./models/quadbike.glb'));

export class Quad {
  readonly root = new THREE.Group(); // on the ground under the quad, turned to its heading
  private tilt = new THREE.Group(); // pitch along the ground, roll on the springs
  private bars?: THREE.Object3D;
  private rear?: THREE.Object3D;
  private knuckles: THREE.Object3D[] = [];
  private fronts: THREE.Object3D[] = [];
  private lens: THREE.MeshStandardMaterial[] = [];
  private model?: THREE.Object3D;
  private headlight?: Headlight;
  private tracks = [new TyreTrack(), new TyreTrack()];
  private tier = 1;
  private heading = NaN;
  private pitch = 0;
  private wheelie = 0;
  private roll = 0;
  private corner = 0; // -1..1, + = turning left hard
  private lag = 0; // the passenger's lean, a little behind the corner
  private steer = 0;
  private forward = NaN;
  private accel = 0;
  private grounded = true;
  private airTime = 0;
  private dustOwed = 0;
  private glow = 0;
  private disposed = false;
  private readonly pose: RidePose = {
    seat: new THREE.Vector3(),
    grips: [new THREE.Vector3(), new THREE.Vector3()],
    pegs: [new THREE.Vector3(-PEG.x, PEG.y, PEG.z), PEG.clone()],
    lean: 0, twist: 0, tuck: 0,
    perch: PERCH, climb: CLIMB, toe: CLIMB,
  };
  private readonly back: RidePose = {
    seat: new THREE.Vector3(),
    grips: [new THREE.Vector3(-PILLION_GRIP.x, PILLION_GRIP.y, PILLION_GRIP.z), PILLION_GRIP.clone()],
    pegs: [new THREE.Vector3(-PILLION_PEG.x, PILLION_PEG.y, PILLION_PEG.z), PILLION_PEG.clone()],
    lean: 0, twist: 0, tuck: 0,
    perch: 0, climb: PILLION_CLIMB, toe: PILLION_TOE,
  };

  constructor(scene: THREE.Object3D) {
    this.tilt.rotation.order = 'YXZ';
    this.root.add(this.tilt);
    scene.add(this.root);
    addHeadlights(scene);
    this.headlight = claimHeadlight();
    loadQuadModel().then(
      (gltf) => {
        if (this.disposed) return;
        const model = gltf.scene.clone(true);
        model.traverse((o) => {
          const m = o as THREE.Mesh;
          if (!m.isMesh) return;
          m.castShadow = m.receiveShadow = true;
          // The lens gets its own material (clones share the model's), so each quad's glow is its own.
          const mat = m.material as THREE.MeshStandardMaterial;
          if (mat.name === 'lamp') {
            const lens = mat.clone();
            lens.emissive.setHex(HEADLIGHT.color);
            lens.emissiveIntensity = 0;
            m.material = lens;
            m.userData.noTier = true;
            this.lens.push(lens);
          }
        });
        this.bars = model.getObjectByName('Handlebar');
        this.rear = model.getObjectByName('RearAxle');
        this.knuckles = ['SteerFL', 'SteerFR'].flatMap((n) => model.getObjectByName(n) ?? []);
        this.fronts = ['WheelFL', 'WheelFR'].flatMap((n) => model.getObjectByName(n) ?? []);
        this.tilt.add(model);
        this.model = model;
        applyTier(model, this.tier);
      },
      (e) => console.warn('sand quad model failed to load', e),
    );
  }

  /** The look of its parts' tier (0 Scrap .. 3 Space-grade). */
  setTier(tier: number) {
    this.tier = tier;
    if (this.model) applyTier(this.model, tier);
  }

  update(p: BikePose, dt: number) {
    const k = (rate: number) => 1 - Math.exp(-dt * rate);
    if (!Number.isFinite(this.heading)) this.heading = p.heading;
    const turn = Math.atan2(Math.sin(p.heading - this.heading), Math.cos(p.heading - this.heading));
    this.heading = p.heading;
    const fx = -Math.sin(p.heading), fz = -Math.cos(p.heading);
    const forward = p.vx * fx + p.vz * fz;
    const rate = dt > 0 ? turn / dt : 0;
    if (dt > 0 && Number.isFinite(this.forward)) this.accel += ((forward - this.forward) / dt - this.accel) * k(5);
    this.forward = forward;

    // How hard it corners (sideways acceleration), the roll out of it, and the nose squatting back on the throttle.
    const corner = p.grounded ? Math.max(-1, Math.min(1, (forward * rate) / FULL_CORNER)) : this.corner * 0.98;
    this.corner += (corner - this.corner) * k(6);
    this.lag += (this.corner - this.lag) * k(3);
    this.roll += (-MAX_ROLL * this.corner - this.roll) * k(8);
    const squat = Math.max(-0.04, Math.min(0.04, this.accel * 0.006));
    this.pitch += (p.nose + squat - this.pitch) * k(p.grounded ? 14 : 30);
    const wheelie = p.grounded && p.jumpHeld ? (p.tow ? WHEELIE_TOW : WHEELIE) : 0;
    this.wheelie += (wheelie - this.wheelie) * k(wheelie > this.wheelie ? 6 : p.grounded ? 12 : 3);
    const steer = Math.abs(forward) > 0.5 ? Math.max(-MAX_STEER, Math.min(MAX_STEER, Math.atan((rate * WHEELBASE) / forward))) : this.steer;
    this.steer += (steer - this.steer) * k(10);
    const landed = p.grounded && !this.grounded;
    if (landed && this.airTime > BIG_AIR) bikeLandSound.play(p.x, p.z, Math.max(0, -p.vy) + this.airTime * 2);
    this.airTime = p.grounded ? 0 : this.airTime + dt;
    this.grounded = p.grounded;

    this.root.position.set(p.x, p.y, p.z);
    this.root.rotation.y = p.heading;
    // Up on the back wheels about the rear axle's contact, as the bike's (src/bike.ts).
    const a = this.pitch, b = this.pitch + this.wheelie, rear = WHEELBASE / 2;
    this.tilt.position.set(0, rear * (Math.sin(b) - Math.sin(a)), rear * (Math.cos(a) - Math.cos(b)));
    this.tilt.rotation.x = b;
    this.tilt.rotation.z = this.roll;
    this.bars?.quaternion.setFromAxisAngle(STEER_AXIS, this.steer);
    // Ackermann: each front wheel points at the turn's centre, the inside one more.
    const r = Math.abs(this.steer) > 1e-4 ? WHEELBASE / Math.tan(this.steer) : Infinity;
    for (let i = 0; i < this.knuckles.length; i++) {
      const x = (i === 0 ? -1 : 1) * KINGPINS / 2; // the turn's centre is r to the left (a right turn's: r < 0)
      this.knuckles[i].rotation.y = Number.isFinite(r) ? Math.atan(WHEELBASE / (r + x)) : 0;
    }
    for (const w of this.fronts) w.rotation.x -= (forward * dt) / FRONT_R;
    if (this.rear) this.rear.rotation.x -= (forward * dt) / REAR_R;
    this.lights(dt);

    // Two tyre tracks and dust off the back wheels.
    if (!p.grounded || p.y > heightAt(p.x, p.z) + 0.05) {
      for (const t of this.tracks) t.break();
      return;
    }
    this.dust(p, fx, fz, Math.hypot(p.vx, p.vz), dt, landed);
    const bx = p.x - fx * rear, bz = p.z - fz * rear;
    for (let i = 0; i < 2; i++) {
      const side = (i === 0 ? -1 : 1) * TRACK / 2;
      const x = bx - fz * side, z = bz + fx * side;
      if (biome('mudflat', x, z) > 0.5) this.tracks[i].break();
      else this.tracks[i].to(x, z);
    }
  }

  /** The headlight: on once it is dark, with a quick ramp so it doesn't pop (as the bike's). */
  private lights(dt: number) {
    const on = nightLevel.value > 0.05 ? 1 : 0;
    this.glow += (on - this.glow) * (1 - Math.exp(-dt * 12));
    if (this.glow < 1e-3) this.glow = 0;
    for (const m of this.lens) m.emissiveIntensity = HEADLIGHT.glow * this.glow;
    const h = this.headlight?.light;
    if (!h) return;
    h.intensity = this.bars ? HEADLIGHT.intensity * this.glow : 0;
    h.shadow.autoUpdate = h.intensity > 0;
    if (!h.intensity) return;
    this.root.updateMatrixWorld(true);
    this.bars!.localToWorld(h.position.copy(LAMP));
    this.bars!.localToWorld(h.target.position.copy(LAMP).add(AIM));
    h.updateMatrixWorld();
    h.target.updateMatrixWorld();
  }

  /** Sand off the back tyres: with speed, more when the back slides sideways, a burst on landing. */
  private dust(p: BikePose, fx: number, fz: number, hs: number, dt: number, landed: boolean) {
    const slip = Math.abs(-p.vx * fz + p.vz * fx);
    this.dustOwed += dt * (Math.max(0, hs - 1.5) * 1.8 + slip * 7) + (landed ? 16 : 0);
    const throwBack = Math.min(hs, 20) * 0.12;
    for (; this.dustOwed >= 1; this.dustOwed--) {
      const side = (Math.random() < 0.5 ? -1 : 1) * TRACK / 2 + (Math.random() - 0.5) * 0.25;
      const x = p.x - fx * WHEELBASE * 0.5 - fz * side, z = p.z - fz * WHEELBASE * 0.5 + fx * side;
      const back = throwBack * (0.4 + Math.random()), spread = (Math.random() - 0.5) * 2;
      tyreDust.emit(x, heightAt(x, z) + 0.15, z, -fx * back - fz * spread, 0.8 + Math.random() * 1.6, -fz * back + fx * spread, 0.8 + Math.random() * 0.6 + hs * 0.045);
    }
  }

  /** The tow ball where it's drawn this frame (world), after update(): the towed cart hangs from it. */
  hitchAt(out: THREE.Vector3): THREE.Vector3 {
    this.root.updateMatrixWorld(true);
    return this.tilt.localToWorld(out.copy(HITCH));
  }

  /** The drawn pitch (rad, + = nose up): along the sand or the flight, plus the wheelie. */
  get drawnPitch() {
    return this.pitch + this.wheelie;
  }

  /** How far it rolls (rad, + = left): out of the turn, a little. */
  get leanAngle() {
    return this.roll;
  }

  /** Put a rider's or passenger's root in the quad's tilted frame (then pose it with rider() or passenger()). */
  seat(rider: THREE.Object3D) {
    this.root.updateMatrixWorld(true);
    this.tilt.matrixWorld.decompose(rider.position, rider.quaternion, tmpScale);
  }

  /** Where the seated rider's hips, hands and feet go (in the quad's tilted frame, after seat()), and its body English. */
  rider(): RidePose {
    const r = this.pose;
    const c = this.corner; // + = left
    // The quad stays flat, so the rider leans: hips slid across the seat to the inside, the upper body thrown over
    // further than on the bike, the shoulders turned with the bars. Sat up straighter than on the bike, rocking back on
    // the throttle and forward on the brakes, over the bars on a wheelie.
    r.seat.copy(SEAT).setX(-0.1 * c);
    r.lean = 0.4 * c - this.roll;
    r.twist = 0.5 * this.steer;
    r.tuck = (this.grounded ? 0.3 : 0.45) + this.wheelie * 0.6 - Math.max(-0.15, Math.min(0.15, this.accel * 0.02));
    for (let i = 0; i < 2; i++) {
      const g = r.grips[i].set(i === 0 ? -GRIP.x : GRIP.x, GRIP.y, GRIP.z);
      if (this.bars) this.tilt.worldToLocal(this.bars.localToWorld(g));
      else g.add(BARS_PIVOT);
    }
    return r;
  }

  /** The passenger's seat behind the rider, as rider(): upright, holding on, leaning in after the rider does, thrown
   *  back a little as the quad pulls away and forward as it brakes; hunched in the air. */
  passenger(): RidePose {
    const r = this.back;
    r.seat.copy(PILLION_SEAT).setX(-0.05 * this.lag);
    r.lean = 0.25 * this.lag - this.roll;
    r.twist = 0.15 * this.lag;
    r.tuck = (this.grounded ? 0 : 0.25) + this.wheelie * 0.8 - Math.max(-0.15, Math.min(0.15, this.accel * 0.025));
    return r;
  }

  dispose() {
    this.disposed = true;
    this.root.removeFromParent();
    this.root.traverse((o) => o.dispose()); // bindings are per quad; geometry and tier materials are shared
    for (const material of this.lens) material.dispose();
    releaseHeadlight(this.headlight);
  }
}

const tmpScale = new THREE.Vector3();
